    let out = compile_and_run(
        r#\"<?php
\$h = tmpfile();
fwrite(\$h, \"seed\");
fflush(\$h);
\$uri = stream_get_meta_data(\$h)[\"uri\"];
echo var_export(file_exists(\$uri), true), \"|\";
unset(\$h);
echo var_export(file_exists(\$uri), true);
\"#,
    );
    assert_eq!(out, \"true|false\");
}

'''
